import{_ as n,C as o,c as r,o as i,a3 as s,G as a}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Assign and track","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/assign-and-track/index.md","filePath":"master/sales/crm/assign-and-track/index.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/assign-and-track/index.md"};function g(h,e,d,m,p,c){const t=o("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=s(`<h1 id="assign-and-track" tabindex="-1">Assign and track <a class="header-anchor" href="#assign-and-track" aria-label="Permalink to &quot;Assign and track&quot;">​</a></h1><p>This group is about giving leads to the right people and judging which ones to chase first. You build sales teams, let Aureus hand out leads by rules, plan follow-ups, and score leads by their chance of winning.</p><blockquote><p><strong>In simple words:</strong> Give each lead an owner, then work the likely wins first.</p></blockquote><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>New lead or opportunity (no team, no salesperson)</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Automatic Lead Assignment is on?</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        +-- Manually:    you click Assign now (or Assign Leads on a team)</span></span>
<span class="line"><span>        +-- Repeatedly:  runs on its schedule, and at once for each new record</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Step 1: pick a sales team by the team&#39;s Assignment Rules</span></span>
<span class="line"><span>Step 2: pick a salesperson by the member&#39;s rules and free capacity</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Owner follows up (activities) --&gt; Probability shows the chance of winning</span></span></code></pre></div><ol><li><strong>Teams.</strong> Set up your sales teams and add members. See <a href="./../pipeline/manage-sales-teams.html">Manage sales teams</a>.</li><li><strong>Assign.</strong> Switch on <strong>Automatic Lead Assignment</strong> and set the rules, as described below.</li><li><strong>Follow up.</strong> Plan calls and emails as activities. See <a href="./../pipeline/schedule-activities.html">Schedule activities</a>.</li><li><strong>Score.</strong> Let Aureus calculate a win chance for each record. See <a href="./lead-scoring.html">Lead scoring</a>.</li><li><strong>Review.</strong> Check how leads and activities perform in <a href="./../reporting/">Reporting</a>.</li></ol><div class="info custom-block"><p class="custom-block-title">About the example</p><p>Sharma Textiles sends three enquiries in one week. The <strong>Sales</strong> team has two members. Aureus shares the leads between them, so nobody waits for a manager.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Automatic assignment is off until you switch it on.</p><ol><li>Go to <code>CRM → Settings → Manage CRM</code>.</li><li>Switch on <strong>Automatic Lead Assignment</strong>.</li><li>Choose how it runs.</li><li>Click <strong>Save changes</strong>.</li></ol>`,10)),a(t,{src:"/images1/crm/settings-auto-assignment-running.png",alt:"Manage CRM settings with Automatic Lead Assignment on and Running set to Repeatedly, with Repeat every 1 and Unit Days"}),e[1]||(e[1]=s('<ul><li><strong><em>Automatic Lead Assignment:</em></strong> The main switch. All sales teams follow it by default.</li><li><strong><em>Running:</em></strong> Required once the switch is on. <ul><li><strong>Manually:</strong> Aureus assigns only when you ask.</li><li><strong>Repeatedly:</strong> Aureus assigns on a schedule, and also each time a new lead or opportunity is created.</li></ul></li><li><strong><em>Repeat every:</em></strong> A whole number, at least 1. It shows for <strong>Repeatedly</strong>.</li><li><strong><em>Unit:</em></strong> <strong>Minutes</strong>, <strong>Hours</strong>, <strong>Days</strong> or <strong>Weeks</strong>. It shows for <strong>Repeatedly</strong>.</li></ul><h2 id="assign-now" tabindex="-1">Assign now <a class="header-anchor" href="#assign-now" aria-label="Permalink to &quot;Assign now&quot;">​</a></h2><p>When the switch is on, the <strong>Assign now</strong> button appears at the top of the <strong>Manage CRM</strong> page.</p><ol><li>Click <strong>Assign now</strong>.</li><li>Read the message and confirm.</li></ol><p>Aureus then reports how many leads went to teams and how many went to salespeople.</p>',5)),a(t,{src:"/images1/crm/assign-now-confirm.png",alt:"Assign now confirmation window on the Manage CRM page"}),e[2]||(e[2]=s('<h2 id="how-aureus-assigns" tabindex="-1">How Aureus assigns <a class="header-anchor" href="#how-aureus-assigns" aria-label="Permalink to &quot;How Aureus assigns&quot;">​</a></h2><p>Aureus works through open leads and opportunities that have no owner. It takes those with the highest priority first, then the oldest.</p><p><strong>Step 1: the team.</strong> A record with no team goes to a team whose <strong>Assignment Rules</strong> it matches. Only active teams are used, and teams that skip assignment are left out. When several teams match, the one with the most free capacity gets it. If the record already has a salesperson, Aureus prefers a team that salesperson belongs to.</p><p><strong>Step 2: the salesperson.</strong> A record with a team but no salesperson goes to a member of that team. A member qualifies when all of these are true:</p><ul><li>The member is <strong>Active</strong> and does not skip automatic assignment.</li><li>The member has received fewer leads than <strong>Max leads (30 days)</strong> in the last 30 days.</li><li>The record matches the member&#39;s own <strong>Assignment rules</strong>.</li></ul><p>If several members qualify, the one with the lightest load compared with their maximum gets the record. When a lead goes to a salesperson and the team works with opportunities, Aureus converts it to an opportunity at once, without creating a customer.</p><h3 id="team-assignment-rules" tabindex="-1">Team assignment rules <a class="header-anchor" href="#team-assignment-rules" aria-label="Permalink to &quot;Team assignment rules&quot;">​</a></h3><p>Open <code>CRM → Configuration → Sales Teams</code>, open a team, then open its <strong>Assignment Rules</strong> tab. The tab shows only when automatic assignment is on.</p><ul><li><strong><em>Conditions:</em></strong> A table with <strong>Field</strong>, <strong>Operator</strong> and <strong>Value</strong>. Click <strong>New Rule</strong> to add a row. With no rows, every record matches.</li><li><strong><em>Field:</em></strong> The record detail to test. You can test <strong>Type</strong>, <strong>Name</strong>, <strong>Contact name</strong>, <strong>Company name</strong>, <strong>Job position</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>Website</strong>, <strong>Street</strong>, <strong>City</strong>, <strong>ZIP</strong>, <strong>State</strong>, <strong>Country</strong>, <strong>Stage</strong>, <strong>Tags</strong>, <strong>Priority</strong>, <strong>Probability (%)</strong>, <strong>Expected revenue</strong>, <strong>Expected closing</strong>, <strong>Created on</strong>, <strong>Campaign</strong>, <strong>Medium</strong>, <strong>Source</strong> and <strong>Referred by</strong>.</li><li><strong><em>Operator:</em></strong> The test to run, such as <strong>contains</strong>, <strong>is equal to</strong>, <strong>starts with</strong>, <strong>greater than</strong>, <strong>is in</strong>, <strong>is set</strong> or <strong>is not set</strong>. The list depends on the field.</li><li><strong><em>Value:</em></strong> What to compare with.</li></ul><p>The text above the table says whether a record must match <strong>all</strong> or <strong>any</strong> of the rules. The page also shows how many records match now. A window lists them.</p><p><strong>Example:</strong> For the team <strong>Sales</strong>, add a rule where <strong>Country</strong> <strong>is in</strong> <strong>India</strong>. Leads from India now go to this team.</p><h3 id="team-members" tabindex="-1">Team members <a class="header-anchor" href="#team-members" aria-label="Permalink to &quot;Team members&quot;">​</a></h3><p>Open the <strong>Members</strong> tab of the team. Click <strong>Add member</strong> to add a salesperson. Each member has these fields.</p><ul><li><strong><em>Salesperson:</em></strong> The user to add. Required. If <strong>Salespeople in Multiple Teams</strong> is off, a user in another team is moved after you confirm.</li><li><strong><em>Max leads (30 days):</em></strong> The most leads this person may receive in 30 days. It starts at 30. Required. It shows only when automatic assignment is on.</li><li><strong><em>Skip auto assignment:</em></strong> Switch on to stop new leads going to this person for now. It shows only when automatic assignment is on.</li><li><strong><em>Active:</em></strong> Switch off to take the member out of assignment. It starts on.</li><li><strong>Assignment rules:</strong> The same rule table as for the team. They limit which records this member can receive.</li></ul><p>A card shows the lead limit, such as <code>Lead limit (30 days): 4 / 30</code>.</p><h3 id="assign-leads-from-a-team" tabindex="-1">Assign leads from a team <a class="header-anchor" href="#assign-leads-from-a-team" aria-label="Permalink to &quot;Assign leads from a team&quot;">​</a></h3><p>A team page also has an <strong>Assign Leads</strong> button. It shows when automatic assignment is on and the team is editable. Aureus lists unassigned leads that fit the team&#39;s rules. All are ticked. Remove any you want to keep out, then click <strong>Assign</strong>. A message tells you how many were assigned and how many could not be given out.</p><h2 id="how-probability-shows-on-records" tabindex="-1">How probability shows on records <a class="header-anchor" href="#how-probability-shows-on-records" aria-label="Permalink to &quot;How probability shows on records&quot;">​</a></h2><p>Every lead and opportunity has a <strong>Probability</strong> in percent. You see it in the lead form and on the lead page, and in the <strong>Probability</strong> column and filters of the opportunity list.</p><ul><li>It is <strong>Automatic</strong> until you type your own number. Aureus then keeps your number.</li><li>The information icon opens <strong>Probability details</strong> with the reasons behind the computed value.</li><li>The refresh icon, <strong>Use computed probability</strong>, returns to the automatic value.</li><li>Moving an opportunity to the won stage sets it to 100 %. Marking it as lost sets it to 0 %.</li></ul><p>See <a href="./lead-scoring.html">Lead scoring</a>.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it helps you do</th></tr></thead><tbody><tr><td><a href="./lead-scoring.html">Lead scoring</a></td><td>Calculate the probability of winning from past results.</td></tr><tr><td><a href="./../pipeline/manage-sales-teams.html">Manage sales teams</a></td><td>Create teams, set targets and add members.</td></tr><tr><td><a href="./../pipeline/schedule-activities.html">Schedule activities</a></td><td>Plan and track follow-ups.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with <strong>Manually</strong> and click <strong>Assign now</strong> a few times. Switch to <strong>Repeatedly</strong> when the results look right.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Rules that match nothing leave records unassigned. Check the <strong>Unassigned</strong> view in <code>CRM → Leads → Leads</code> after each run.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../configuration/settings.html">CRM settings</a></li><li><a href="./../acquire-leads/create-lead.html">Create a lead</a></li><li><a href="./../acquire-leads/convert-lead.html">Convert a lead</a></li><li><a href="./../">CRM overview</a></li></ul>',27))])}const b=n(l,[["render",g]]);export{w as __pageData,b as default};
